# ── Jun 2026 — REMOTE IMAGES IN THE RELEASE APK ────────────────────
# Every product photo was blank in the signed Android build while the
# same URL opened fine in Chrome. React Native's <Image> renders through
# FRESCO (com.facebook.drawee / imagepipeline / imageutils / animated)
# and fetches through OkHttp. The existing rules only kept
# `com.facebook.react.**`, so R8 + resource shrinking stripped Fresco's
# native-code bridges and OkHttp's platform classes out of the release
# APK. Debug builds (no R8) therefore worked and release builds did not.
-keep class com.facebook.drawee.** { *; }
-keep class com.facebook.imagepipeline.** { *; }
-keep class com.facebook.imagepipeline.nativecode.** { *; }
-keep class com.facebook.imageformat.** { *; }
-keep class com.facebook.imageutils.** { *; }
-keep class com.facebook.animated.** { *; }
-keep class com.facebook.fresco.** { *; }
-keep class com.facebook.common.** { *; }
-keep class com.facebook.soloader.** { *; }
-keepclassmembers class * { native <methods>; }
-dontwarn com.facebook.drawee.**
-dontwarn com.facebook.imagepipeline.**
-dontwarn com.facebook.animated.**
-keep class okhttp3.** { *; }
-keep class okio.** { *; }
-keep interface okhttp3.** { *; }
-keep class org.conscrypt.** { *; }
-dontwarn org.conscrypt.**
-keep class com.facebook.react.modules.network.** { *; }
-keep class kotlin.Metadata { *; }
-keepclassmembers class **$WhenMappings { <fields>; }
-keepclassmembers class kotlin.Metadata { public <methods>; }
-keep class kotlinx.coroutines.android.AndroidDispatcherFactory { *; }
-dontwarn kotlinx.coroutines.**
-keep class * implements android.os.Parcelable { public static final ** CREATOR; }
-keepclassmembers enum * { public static **[] values(); public static ** valueOf(java.lang.String); }
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod,Exceptions
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile
